#!/usr/bin/env python3
import sys

def increment_base36(s: str) -> str:
    """Increment a base36 string by 1, returning zero-padded result."""
    # Convert from base36 to integer
    val = 0
    for ch in s:
        if '0' <= ch <= '9':
            val = val * 36 + (ord(ch) - ord('0'))
        elif 'A' <= ch <= 'Z':
            val = val * 36 + (ord(ch) - ord('A') + 10)
        elif 'a' <= ch <= 'z':
            val = val * 36 + (ord(ch) - ord('a') + 10)
    # Increment
    val += 1
    # Convert back to base36
    digits = []
    if val == 0:
        digits.append('0')
    while val > 0:
        remainder = val % 36
        if remainder < 10:
            digits.append(chr(ord('0') + remainder))
        else:
            digits.append(chr(ord('A') + remainder - 10))
        val //= 36
    result = ''.join(reversed(digits))
    # Zero-pad to original length
    return result.zfill(len(s))


def main():
    try:
        with open('ids.txt', 'r') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    # Extract the 4-character suffix after "ORD-"
    if not last_id.startswith("ORD-"):
        print("ORD-0000")
        return

    suffix = last_id[4:]
    next_suffix = increment_base36(suffix)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

