"""Generate the next order id.

Reads ids.txt (one id per line, most recent last) and prints the next
id in sequence.  Ids have the form ORD- followed by four base-36
characters (0-9 A-Z).
"""

import os
import sys


def base36_encode(n: int, width: int = 4) -> str:
    """Encode *n* as a zero-padded base-36 string of *width* characters."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        n, rem = divmod(n, 36)
        result.append(chars[rem])
    return "".join(reversed(result))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def main() -> None:
    ids_path = os.path.join(os.getcwd(), "ids.txt")

    try:
        with open(ids_path) as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    suffix = last_id.removeprefix("ORD-")

    try:
        n = base36_decode(suffix)
    except ValueError:
        print(f"error: could not parse last id {last_id!r}", file=sys.stderr)
        sys.exit(1)

    next_id = f"ORD-{base36_encode(n + 1)}"
    print(next_id)


if __name__ == "__main__":
    main()

