import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int) -> str:
    """Convert an integer to a zero-padded 4-character base-36 string."""
    digits = []
    for _ in range(4):
        digits.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a 4-character base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def main():
    try:
        with open('ids.txt') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print('ORD-0000')
        return

    # Find the last non-empty line with a valid id
    last_id = None
    for line in reversed(lines):
        stripped = line.strip()
        if not stripped:
            continue
        parts = stripped.split('\t')
        id_part = parts[-1] if len(parts) > 1 else parts[0]
        if id_part.startswith('ORD-') and len(id_part) == 8:
            last_id = id_part
            break

    if last_id is None:
        print('ORD-0000')
        return

    suffix = last_id[4:]  # the 4-character base-36 part
    num = from_base36(suffix)
    next_num = num + 1
    next_suffix = to_base36(next_num)
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

