#!/usr/bin/env python3
"""Read ids.txt and print the next order id to stdout."""

from pathlib import Path


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base-36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        chars[n % 36]
        n //= 36
    return "".join(result)


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def next_id(current: str) -> str:
    """Given an ORD-XXXX id, return the next id."""
    suffix = current.split("-", 1)[1]
    n = int(suffix, 36)
    next_suffix = base36_encode(n + 1, width=len(suffix))
    return f"ORD-{next_suffix}"


def main() -> None:
    txt = Path("ids.txt")
    lines = txt.read_text().splitlines()
    # Skip empty trailing lines
    while lines and not lines[-1].strip():
        lines.pop()

    if not lines:
        raise SystemExit("error: ids.txt is empty")

    last_id = lines[-1].strip()
    print(next_id(last_id), end="")


if __name__ == "__main__":
    main()

