    digits = []
    while n > 0:
        digits.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    n = 0
    for c in s:
        n = n * 36 + BASE36.index(c)
    return n


def next_id(last_id: str) -> str:
    """Given an ID like ORD-243G, return the next sequential ID."""
    prefix, suffix = last_id.rsplit('-', 1)
    num = from_base36(suffix)
    next_num = num + 1
    next_suffix = to_base36(next_num).zfill(len(suffix))
    return f'{prefix}-{next_suffix}'


def main():
    last_id = None
    try:
        with open('ids.txt') as f:
            for line in f:
                line = line.strip()
                if line:
                    last_id = line
    except FileNotFoundError:
        print('ORD-0000')
        return

    if last_id is None:
        print('ORD-0000')
        return

    print(next_id(last_id))


