#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

import os
import re


def natural_sort_key(name):
    """Generate a sort key for natural (human) ordering of filenames."""
    return [
        int(text) if text.isdigit() else text.lower()
        for text in re.split(r"(\d+)", name)
    ]


def main():
    reports_dir = os.path.join(os.path.dirname(__file__), "reports")
    files = sorted(os.listdir(reports_dir), key=natural_sort_key)
    for f in files:
        print(f)


if __name__ == "__main__":
    main()

