#!/usr/bin/env python3
"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every entry in app.log whose
timestamp is strictly older than 7 days before AS_OF is moved to archive.log
(appended, preserving order). The remaining entries stay in app.log in their
original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_ts(line: str) -> datetime | None:
    """Try to parse a leading 'YYYY-MM-DD HH:MM:SS' from *line*."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    # Read all lines from app.log, preserving order.
    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        if not line.strip():
            # Preserve blank lines in keep (they have no timestamp to compare)
            keep.append(line)
            continue
        ts = parse_ts(line)
        if ts is None or ts >= cutoff:
            keep.append(line)
        else:
            archive.append(line)

    # Rewrite app.log with entries that stay.
    with open("app.log", "w") as f:
        f.writelines(keep)

    # Append archived entries (preserving order).
    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

